def save(path, obj):
    path.write_text(json.dumps(obj, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')

def claim(text, refs):
    return {'text': text, 'exhibit_ids': refs.split()}

def item(eid, title, observation, interpretation, uncertainty, timestamp=None):
    return {'exhibit_id': eid, 'title': title, 'source_path': f'images/{eid}.png' if eid.startswith('V') else {'D01':'documents/D01_access.csv','D02':'documents/D02_witnesses.md','D03':'documents/D03_messages.md'}[eid], 'timestamp': timestamp, 'direct_observation': observation, 'interpretation': interpretation, 'uncertainty': uncertainty}

def event(t, text, refs, status='confirmed_record', raw=None):
    return {'time': t, 'raw_time': raw or t, 'status': status, 'description': text, 'exhibit_ids': refs.split()}

