def cites(refs): return ' ['+', '.join(refs)+']'
def bullets(items): return '\n'.join('- '+i['text']+cites(i['exhibit_ids']) for i in items)

for cid,c in CASES.items():
    d=OUT/cid; d.mkdir(exist_ok=True)
    save(d/'timeline.json',c['timeline'])
    save(d/'evidence_analysis.json',{'schema_version':'1.0','case_id':cid,'context_source':'case_brief.md','context_observations':'Fictional synthetic schematic case. Prototype last confirmed 18:00 and missing 18:18. Shift assignments: Nora teal, Eli orange, Maya purple, Theo blue, Ada red. Coat colour is not biometric identity.','exhibits':c['evidence']})
    save(d/'conclusions.json',c['conclusions'])
    md=f"# {cid.replace('_',' ').title()} — investigation report\n\n## 1. Executive summary\n\n{c['summary']}{cites(c['conclusions']['exhibit_ids'])}\n\n## 2. Evidence inventory\n\nAll 10 images were visually inspected, and all three document exhibits plus the case brief were read. Exhibit IDs are local to this case. The brief supplies the five coat assignments; these are not biometric identification.\n"
    for e in c['evidence']:
        md+=f"\n### {e['exhibit_id']} — {e['title']}\n\n- Source: `{e['source_path']}`.\n- Timestamp: {e['timestamp'] or 'No event timestamp supplied'}.\n- Direct observation: {e['direct_observation']}\n- Interpretation: {e['interpretation']}\n- Uncertainty: {e['uncertainty']}\n"
    md+='\n## 3. Timeline\n\n“Confirmed record” describes what the exhibit records, not authenticated personal identity.\n\n| Time | Status | Event and sources |\n|---|---|---|\n'
    for e in c['timeline']['events']: md+=f"| {e['time']} | {e['status'].replace('_',' ')} | {e['description']}{cites(e['exhibit_ids'])} |\n"
    md+='\n### Assumptions\n\n'+bullets(c['timeline']['assumptions'])+'\n\n### Missing intervals and probable movements\n\n'+bullets(c['timeline']['missing_intervals_and_movements'])
    md+='\n\n## 4. Suspect analysis\n'
    for s in c['suspects']:
        md+=f"\n### {s['name']}\n\n**{s['assessment']}**{cites(s['exhibit_ids'])}\n\n"+'\n'.join('- **'+k.replace('_',' ').capitalize()+':** '+s[k] for k in ['opportunity','access','timeline_consistency','supporting_evidence','exculpatory_evidence','uncertainty'])+'\n'
    md+='\n## 5. Key deductions\n\n'+bullets(c['deductions'])+'\n\n## 6. Contradictions\n\n'+bullets(c['contradictions'])
    md+='\n\n## 7. Final conclusion\n\n'+c['summary']+cites(c['conclusions']['exhibit_ids'])+'\n\n**No responsible individual is definitively identified.**\n\n### Plausible alternatives\n\n'+bullets(c['conclusions']['alternatives'])
    md+='\n\n## 8. Confidence and limitations\n\n'+'\n'.join('- **'+k.replace('_',' ').capitalize()+':** '+v for k,v in c['conclusions']['confidence'].items())+'\n\n'+bullets(c['conclusions']['limitations'])
    md+='\n\n## 9. Recommended next investigative steps\n\n'+bullets(c['steps'])+'\n'
    (d/'investigation_report.md').write_text(md,encoding='utf-8')

ESC=html.escape
def hc(cid,refs): return ' <span class="refs">'+''.join(f'<a href="#{cid}-{r}">{r}</a>' for r in refs)+'</span>'
def hl(cid,items): return '<ul>'+''.join('<li>'+ESC(i['text'])+hc(cid,i['exhibit_ids'])+'</li>' for i in items)+'</ul>'

