for cid,c in CASES.items():
    parts.append(f'<article class="case" id="{cid}"><div class="eyebrow">{cid.replace("_"," ")} · independent record</div><h2>{ESC(c["headline"])}</h2><div class="verdict"><span class="badge">18:00–18:18 disappearance window</span><span class="badge">No definitive individual identification</span><p>{ESC(c["summary"])}{hc(cid,c["conclusions"]["exhibit_ids"])}</p></div><nav class="sectionlinks" aria-label="{cid} sections">'+''.join(f'<a href="#{cid}-{anchor}">{label}</a>' for anchor,label in [('timeline','Timeline'),('suspects','Suspects'),('deductions','Deductions'),('contradictions','Contradictions'),('confidence','Confidence'),('evidence','Evidence')])+'</nav>')
    parts.append(f'<h3 id="{cid}-timeline">Chronology & missing intervals</h3><p class="small">Times have minute precision and no supplied date or timezone. A confirmed record is an observation in an exhibit, not authenticated human identity.</p><div class="timeline">')
    for e in c['timeline']['events']:
        parts.append(f'<div class="event"><time>{e["time"]}</time><span class="status">{e["status"].replace("_"," ")}</span><p>{ESC(e["description"])}{hc(cid,e["exhibit_ids"])}</p></div>')
    parts.append('</div><h4>Assumptions behind the reconstruction</h4>'+hl(cid,c['timeline']['assumptions'])+'<h4>Unobserved intervals & conditional inferences</h4>'+hl(cid,c['timeline']['missing_intervals_and_movements']))
    parts.append(f'<h3 id="{cid}-suspects">Five suspects, evaluated separately</h3><div class="suspects">')
    for s in c['suspects']:
        parts.append(f'<section class="suspect"><h4>{ESC(s["name"])}</h4><p><strong>{ESC(s["assessment"])}</strong>{hc(cid,s["exhibit_ids"])}</p><dl>'+''.join(f'<dt>{k.replace("_"," ").capitalize()}</dt><dd>{ESC(s[k])}</dd>' for k in ['opportunity','access','timeline_consistency','supporting_evidence','exculpatory_evidence','uncertainty'])+'</dl></section>')
    parts.append(f'</div><h3 id="{cid}-deductions">Key deductions</h3>'+hl(cid,c['deductions'])+f'<h3 id="{cid}-contradictions">Contradictions & tensions</h3>'+hl(cid,c['contradictions'])+'<h3>Alternative explanations</h3>'+hl(cid,c['conclusions']['alternatives']))
    parts.append(f'<h3 id="{cid}-confidence">Confidence & limitations</h3><dl class="confidence">'+''.join('<dt>'+k.replace('_',' ').capitalize()+'</dt><dd>'+ESC(v)+'</dd>' for k,v in c['conclusions']['confidence'].items())+'</dl>'+hl(cid,c['conclusions']['limitations'])+'<h3>Next investigative steps</h3>'+hl(cid,c['steps']))
    parts.append(f'<h3 id="{cid}-evidence">Exhibit gallery & examination notes</h3><p>All ten images were inspected at source resolution. Expand an exhibit for the distinction between observation, interpretation, and uncertainty. Documentary exhibits include their complete supplied text.</p><div class="exhibits">')
    public=REPO/'datasets/detective'/cid/'public'
    for e in c['evidence']:
        parts.append(f'<section class="exhibit" id="{cid}-{e["exhibit_id"]}">')
