conclusion_schema['properties'].update({'most_likely_account':{'type':'string'},'exhibit_ids':{'$ref':'#/$defs/refs'},'leading_suspect':{'type':['string','null']},'responsible_individual_definitively_identified':{'type':'boolean'},'confidence':{'type':'object','minProperties':4,'additionalProperties':{'type':'string'}},'suspects':{'type':'array','minItems':5,'maxItems':5,'items':{'type':'object','required':['name','assessment','opportunity','access','timeline_consistency','supporting_evidence','exculpatory_evidence','uncertainty','exhibit_ids'],'properties':{'exhibit_ids':{'$ref':'#/$defs/refs'}}}}})
